import React from 'react';
import { useNavigate } from 'react-router-dom';

function ChooseRole() {
  const navigate = useNavigate();

  return (
    <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', background: '#F8F9FA', padding: '20px' }}>
      <div style={{ width: '100%', maxWidth: '402px', background: 'white', padding: '32px 24px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.08)' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 700 }}>TENTUKAN PERANMU</h1>
        <p style={{ fontSize: '18px', fontWeight: 600 }}>Kamu mau ngapain?</p>
        <p style={{ color: '#475569', marginBottom: '24px' }}>Pilih peran Anda sekarang. Anda selalu bisa berpindah peran nanti.</p>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <div onClick={() => navigate('/dashboard-customer')} style={{ padding: '20px', border: '2px solid #E2E8F0', borderRadius: '16px', cursor: 'pointer' }}>
            <div style={{ fontSize: '32px' }}>👤</div>
            <h3 style={{ fontSize: '16px', fontWeight: 700 }}>Saya membutuhkan pekerja (Customer)</h3>
            <p style={{ color: '#475569' }}>Cari talenta lepas profesional secara instan untuk membantu bisnis Anda.</p>
          </div>
          <div onClick={() => navigate('/dashboard-worker')} style={{ padding: '20px', border: '2px solid #E2E8F0', borderRadius: '16px', cursor: 'pointer' }}>
            <div style={{ fontSize: '32px' }}>💼</div>
            <h3 style={{ fontSize: '16px', fontWeight: 700 }}>Saya ingin bekerja</h3>
            <p style={{ color: '#475569' }}>Temukan job instan yang sesuai keahlianmu dan langsung dapatkan bayaran.</p>
          </div>
        </div>
        <button onClick={() => navigate('/dashboard-customer')} style={{ width: '100%', padding: '14px', background: '#0D9488', color: 'white', border: 'none', borderRadius: '12px', fontSize: '16px', fontWeight: 700, marginTop: '16px' }}>Lanjutkan</button>
      </div>
    </div>
  );
}

export default ChooseRole;
